BEGIN;
INSERT INTO prefixos_frota(codigo) SELECT * FROM unnest(ARRAY['CM','CV','CG','CP','CT','C','CI','CE','CTC','CC','A','ON','VAN','EH','RE','TR','TE','PC','MN','PA','FA','PH','CB','RCP','MC','RC']) ON CONFLICT(codigo) DO NOTHING;
INSERT INTO obras(codigo,nome,descricao) VALUES ('BR369','Pavimentação BR-369','Dados fictícios'),('OBR001','Obra Norte','Dados fictícios'),('OBR002','Obra Sul','Dados fictícios'),('OBR003','Obra Centro','Dados fictícios'),('OBR004','Manutenção Rodoviária','Dados fictícios') ON CONFLICT(codigo) DO UPDATE SET nome=EXCLUDED.nome;
INSERT INTO funcionarios(nome,matricula,cargo) VALUES ('João Teste da Silva','FICT001','Mecânico'),('Carlos Exemplo Pereira','FICT002','Eletricista'),('Marcos Fictício Souza','FICT003','Borracheiro'),('Paulo Demonstração Lima','FICT004','Soldador'),('André Dados de Teste','FICT005','Mecânico'),('Bruno Exemplo Costa','FICT006','Eletricista') ON CONFLICT(matricula) DO UPDATE SET nome=EXCLUDED.nome,cargo=EXCLUDED.cargo;
