(47120,'BR369','CT',12,'INTERNA','BORRACHARIA',NULL,1,'FINALIZADA'),(47121,'BR369','CM',5,'TERCEIRO','AUTO_ELETRICA','Auto Elétrica Exemplo',2,'FINALIZADA'),(47122,'OBR001','CT',12,'MATERIAL',NULL,NULL,3,'ABERTA'),(47123,'OBR001','CT',15,'INTERNA','MECANICA',NULL,4,'EM_ANDAMENTO'),(47124,'OBR002','CV',3,'INTERNA','LUBRIFICACAO',NULL,5,'FINALIZADA'),(47125,'BR369','PC',2,'TERCEIRO','HIDRAULICA','Hidráulica Modelo',6,'AGUARDANDO_PECA'),(47126,'OBR003','VAN',1,'MATERIAL',NULL,NULL,7,'FINALIZADA'),(47127,'OBR004','CG',4,'INTERNA','SOLDAGEM',NULL,8,'FINALIZADA'),(47128,'OBR002','CE',3,'TERCEIRO','BORRACHARIA','Borracharia Fictícia',9,'FINALIZADA'),(47129,'BR369','CT',12,'INTERNA','MECANICA',NULL,10,'ABERTA'),(47130,'OBR001','CM',5,'INTERNA','AUTO_ELETRICA',NULL,11,'FINALIZADA'),(47131,'OBR003','CT',15,'MATERIAL',NULL,NULL,12,'EM_ANDAMENTO'),(47132,'OBR004','PC',2,'TERCEIRO','MECANICA','Retífica Exemplo',13,'FINALIZADA'),(47133,'BR369','CV',3,'INTERNA','FUNILARIA',NULL,14,'CANCELADA'),(47134,'OBR002','VAN',1,'INTERNA','OUTROS',NULL,15,'AGUARDANDO_PECA'),(47135,'OBR003','CG',4,'TERCEIRO','SOLDAGEM','Soldas Teste',16,'FINALIZADA'),(47136,'OBR004','CE',3,'MATERIAL',NULL,NULL,17,'FINALIZADA'),(47137,'BR369','CT',12,'INTERNA','HIDRAULICA',NULL,18,'FINALIZADA'),(47138,'OBR001','CM',5,'TERCEIRO','LUBRIFICACAO','Lubrificadora Exemplo',19,'EM_ANDAMENTO'),(47139,'OBR002','CT',15,'INTERNA','BORRACHARIA',NULL,20,'FINALIZADA'),(47140,'OBR003','PC',2,'MATERIAL',NULL,NULL,21,'ABERTA'),(47141,'OBR004','VAN',1,'INTERNA','AUTO_ELETRICA',NULL,22,'EM_ANDAMENTO'))
INSERT INTO ordens_servico(numero_os,obra_id,prefixo_frota_id,frota_numero,natureza_os,categoria_servico,prestador_terceiro,data_abertura,status,observacoes) SELECT d.numero_os,o.id,p.id,d.num,d.natureza,d.categoria,d.prestador,make_date(2026,8,d.dia),d.status,'Registro fictício para testes' FROM d JOIN obras o ON o.codigo=d.obra JOIN prefixos_frota p ON p.codigo=d.prefixo ON CONFLICT(numero_os) DO UPDATE SET obra_id=EXCLUDED.obra_id,prefixo_frota_id=EXCLUDED.prefixo_frota_id,frota_numero=EXCLUDED.frota_numero,natureza_os=EXCLUDED.natureza_os,categoria_servico=EXCLUDED.categoria_servico,prestador_terceiro=EXCLUDED.prestador_terceiro,data_abertura=EXCLUDED.data_abertura,status=EXCLUDED.status;
WITH x(os,mat) AS(VALUES(47120,'FICT001'),(47120,'FICT003'),(47123,'FICT001'),(47123,'FICT005'),(47124,'FICT001'),(47127,'FICT004'),(47129,'FICT005'),(47130,'FICT002'),(47130,'FICT006'),(47134,'FICT001'),(47134,'FICT005'),(47137,'FICT001'),(47139,'FICT003'),(47141,'FICT002')) INSERT INTO ordens_servico_funcionarios SELECT o.id,f.id,CURRENT_TIMESTAMP FROM x JOIN ordens_servico o ON o.numero_os=x.os JOIN funcionarios f ON f.matricula=x.mat ON CONFLICT DO NOTHING;
WITH x(os,descricao,valor) AS(VALUES(47120,'Troca de pneu',90.00),(47120,'Reparo de câmara',65.00),(47121,'Reparo do alternador',850.00),(47123,'Revisão do motor',680.00),(47123,'Substituição de correia',160.00),(47124,'Troca de óleo',120.00),(47125,'Reparo hidráulico',2450.00),(47127,'Soldagem de suporte',310.00),(47128,'Recapagem de pneus',1380.00),(47129,'Diagnóstico mecânico',95.00),(47130,'Reparo da iluminação',220.00),(47132,'Retífica do motor',7800.00),(47133,'Reparo cancelado',500.00),(47134,'Instalação de acessório',175.00),(47135,'Soldagem especializada',1120.00),(47137,'Troca de mangueira',390.00),(47138,'Lubrificação completa',640.00),(47139,'Reparo de pneu',75.00),(47141,'Diagnóstico elétrico',145.00)) INSERT INTO servicos_os(ordem_servico_id,descricao,valor) SELECT o.id,x.descricao,x.valor FROM x JOIN ordens_servico o ON o.numero_os=x.os WHERE NOT EXISTS(SELECT 1 FROM servicos_os s WHERE s.ordem_servico_id=o.id AND s.descricao=x.descricao);
WITH x(os,descricao,qtd,unidade,valor) AS(VALUES(47120,'Câmara de ar',1.000,'UN',145.00),(47122,'Limpador multiuso',2.000,'UN',25.50),(47122,'Pano industrial',5.000,'UN',8.90),(47123,'Correia do motor',1.000,'UN',285.00),(47123,'Junta',2.000,'UN',68.75),(47124,'Óleo lubrificante',8.000,'L',34.90),(47126,'Fluido de freio',3.000,'L',39.50),(47126,'Lâmpada',4.000,'UN',22.00),(47130,'Lâmpada de farol',2.000,'UN',95.00),(47131,'Graxa',12.500,'KG',31.20),(47131,'Desengraxante',10.000,'L',18.40),(47132,'Kit de juntas',1.000,'UN',1250.00),(47133,'Chapa cancelada',2.000,'UN',280.00),(47136,'Eletrodo',5.000,'KG',42.80),(47136,'Disco de corte',8.000,'UN',16.50),(47137,'Mangueira hidráulica',2.000,'UN',215.00),(47138,'Óleo hidráulico',20.000,'L',29.80),(47140,'Parafuso',30.000,'UN',4.75),(47140,'Porca',30.000,'UN',2.90),(47140,'Arruela',50.000,'UN',1.15)) INSERT INTO produtos_os(ordem_servico_id,descricao,quantidade,unidade,valor_unitario) SELECT o.id,x.descricao,x.qtd,x.unidade,x.valor FROM x JOIN ordens_servico o ON o.numero_os=x.os WHERE NOT EXISTS(SELECT 1 FROM produtos_os p WHERE p.ordem_servico_id=o.id AND p.descricao=x.descricao);
COMMIT;